<?php foreach($itemSeries as $sr): ?><form class="panel set-card" action="<?= e(routeUrl('treinar-salvar')) ?>" method="post"><input type="hidden" name="_csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="id" value="<?= $sid ?>"><input type="hidden" name="item_id" value="<?= $selected ?>"><input type="hidden" name="serie_id" value="<?= (int)$sr['id'] ?>"><div class="set-row"><strong>Série <?= (int)$sr['numero_serie'] ?></strong><span class="pill <?= $sr['concluida']?'active':'archived' ?>"><?= $sr['concluida']?'✓ Concluída':'Pendente' ?></span><?= $sr['origem']==='extra'?'<span class="muted small">Extra</span>':'' ?></div>
