<form method="post" action="<?= e(routeUrl('treinar-adicionar-serie')) ?>"><input type="hidden" name="_csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="id" value="<?= $sid ?>"><input type="hidden" name="item_id" value="<?= $selected ?>"><button class="secondary" type="submit">+ Adicionar série extra</button></form>
<div class="inline-actions"> <?php if($it['status']==='concluido_antecipadamente'||$it['status']==='concluido'): ?><form method="post" action="<?= e(routeUrl('treinar-exercicio')) ?>"><input type="hidden" name="_csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="id" value="<?= $sid ?>"><input type="hidden" name="item_id" value="<?= $selected ?>"><button class="ghost" name="acao" value="reabrir">Reabrir exercício</button></form><?php elseif($it['status']==='parcialmente_realizado'): ?><form method="post" action="<?= e(routeUrl('treinar-exercicio')) ?>" onsubmit="return confirm('Concluir este exercício com as séries já realizadas?');"><input type="hidden" name="_csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="id" value="<?= $sid ?>"><input type="hidden" name="item_id" value="<?= $selected ?>"><button class="ghost" name="acao" value="antecipar">Concluir antecipadamente</button></form><?php endif; ?></div></section>
